61		const n = 16
62		var wg sync.WaitGroup
63		codes := make([]int, n)
64		outputs := make([]string, n)
65		start := make(chan struct{})
66		for i := 0; i < n; i++ {
67			wg.Add(1)
68			go func(i int) {
