217				t.Fatalf("duplicate receipt for %s", r.ProposalID)
218			}
219			executed[r.ProposalID] = true
220		}
221		proposals, err := store.Proposals()
222		if err != nil {
223			t.Fatal(err)
224		}
225		for _, p := range proposals {
226			if p.State == "executed" && !executed[p.ID] {
227				t.Fatalf("proposal %s executed without receipt", p.ID)
228			}
229			if p.State == "passed" && executed[p.ID] {
230				t.Fatalf("proposal %s passed but has receipt", p.ID)
231			}
232		}
233	}
