304		// 截止时刻计票：600 赞成、0 反对、达到法定人数 => passed。
305		if so, se, code := runCLI(t, binary, state, "tally", "--id", "gip-vote-1",
306			"--now", "200", "--json"); code != 0 || !strings.Contains(so, `"passed": true`) {
