310		if _, se, code := runCLI(t, binary, state, "vote", "--id", "gip-vote-1",
311			"--voter", "dave", "--choice", "against", "--now", "150"); code != 1 ||
312			!strings.Contains(se, "already been tallied") {
313			t.Fatalf("post-tally vote code=%d: %s", code, se)
314		}
315		// 再次计票返回首次时间。
316		if so, _, code := runCLI(t, binary, state, "tally", "--id", "gip-vote-1",
317			"--now", "999", "--json"); code != 0 || !strings.Contains(so, `"tallied_at": 200`) {
318			t.Fatalf("repeat tally: %s", so)
319		}
