1104			"--action", "transfer:audits:250", "--action", "transfer:legal:5", "--json"}
1105	
1106		type registerResponse struct {
1107			ID                string   `json:"id"`
1108			State             string   `json:"state"`
1109			TimelockEnd       int64    `json:"timelock_end"`
1110			Actions           []string `json:"actions"`
1111			AlreadyRegistered bool     `json:"already_registered"`
1112		}
1113		runRegister := func() registerResponse {
1114			t.Helper()
1115			so, se, code := runCLI(t, binary, state, register...)
1116			if code != 0 {
1117				t.Fatalf("register exit=%d: %s", code, se)
1118			}
1119			var resp registerResponse
1120			if err := json.Unmarshal([]byte(so), &resp); err != nil {
1121				t.Fatalf("register output is not JSON: %v\n%s", err, so)
1122			}
1123			return resp
1124		}
1125		wantActions := []string{"transfer:audits:250", "transfer:legal:5"}
1126		check := func(resp registerResponse, state string, existed bool) {
1127			t.Helper()
1128			if resp.ID != "gip-1" || resp.TimelockEnd != 100 || resp.State != state ||
1129				resp.AlreadyRegistered != existed || strings.Join(resp.Actions, ",") != strings.Join(wantActions, ",") {
1130				t.Fatalf("register response = %+v, want state=%s already_registered=%v actions=%v",
1131					resp, state, existed, wantActions)
1132			}
1133		}
1134	
1135		// 首次登记：already_registered=false，state=passed。
1136		check(runRegister(), "passed", false)
