443	func runTally(args []string) {
444		cf := newCmdFlags("tally")
445		id := cf.fs.String("id", "", "proposal id to tally")
446		nowRaw := cf.fs.String("now", "", "current timestamp provided by the caller (int64, >= deadline)")
447		cf.parse(args)
448		if *id == "" {
449			fmt.Fprintf(os.Stderr, "usage error: --id is required\n")
