515	func runBalances(args []string) {
516		cf := newCmdFlags("balances")
517		account := cf.fs.String("account", "", "show only this recipient account balance (unknown accounts are 0)")
518		cf.parse(args)
519		store, err := govflow.Open(cf.state)
520		if err != nil {
521			fail(err)
522		}
523		defer store.Close()
524		// 一次快照读取保证资金库与账户余额来自同一份已提交状态，
525		// 不会把并发执行前后的数字拼在一起。
526		snapshot, err := store.BalanceSnapshot()
527		if err != nil {
528			fail(err)
529		}
530		if *account != "" {
531			// 未出现过的账户余额为 0，且不向状态文件新增账户记录。
532			balance := snapshot.Balances[*account]
533			if cf.asJSON {
534				emitJSON(map[string]any{"treasury": snapshot.Treasury, "account": *account, "balance": balance})
535			} else {
536				fmt.Printf("treasury %d\n%s %d\n", snapshot.Treasury, *account, balance)
537			}
538			return
539		}
540		if cf.asJSON {
541			emitJSON(map[string]any{"treasury": snapshot.Treasury, "balances": snapshot.Balances})
542			return
543		}
544		fmt.Printf("treasury %d\n", snapshot.Treasury)
545		accounts := make([]string, 0, len(snapshot.Balances))
546		for acct := range snapshot.Balances {
547			accounts = append(accounts, acct)
548		}
549		sort.Strings(accounts)
550		for _, acct := range accounts {
551			fmt.Printf("%s %d\n", acct, snapshot.Balances[acct])
552		}
553	}
