679	func printProposalText(p govflow.ProposalRecord) {
680		fmt.Printf("proposal %s state=%s timelock_end=%d actions=%d\n", p.ID, p.State, p.TimelockEnd, len(p.Actions))
681		for i, action := range p.Actions {
