686	func printVoteProposalText(v *govflow.VoteProposalView) {
687		fmt.Printf("proposal %s source=vote state=%s quorum=%d voting=[%d,%d) timelock_end=%d actions=%d total_weight=%d\n",
688			v.ID, v.State, v.Quorum, v.StartAt, v.Deadline, v.TimelockEnd, len(v.Actions), v.TotalWeight)
689		for _, m := range v.Members {
690			chain := strings.Join(m.Path, "->")
691			if len(m.Path) == 1 {
692				fmt.Printf("  member %s weight=%d representative=self\n", m.ID, m.Weight)
693			} else {
694				fmt.Printf("  member %s weight=%d path=%s\n", m.ID, m.Weight, chain)
695			}
696		}
697		for i, action := range v.Actions {
698			fmt.Printf("  action %d: %s\n", i, action)
699		}
700		for _, b := range v.Ballots {
701			fmt.Printf("  ballot representative=%s choice=%s weight=%d voted_at=%d\n",
702				b.Representative, choiceWord(b.Support), b.Weight, b.VotedAt)
703		}
704		if v.Tally != nil {
705			verdict := "rejected"
706			if v.Tally.Passed {
707				verdict = "passed"
708			}
709			fmt.Printf("  tally for=%d against=%d turnout=%d => %s tallied_at=%d\n",
710				v.Tally.ForWeight, v.Tally.AgainstWeight, v.Tally.Turnout, verdict, v.Tally.TalliedAt)
711		}
712	}
713	
714	func printReceiptText(r *govflow.Receipt, header bool) {
715		if header {
716			fmt.Printf("receipt proposal=%s order=%d executed_at=%d actions=%d\n", r.ProposalID, r.Order, r.ExecutedAt, len(r.Actions))
717		} else {
718			fmt.Printf("executed proposal %s at %d (%d action(s)); receipt order %d\n", r.ProposalID, r.ExecutedAt, len(r.Actions), r.Order)
719		}
720		for _, ar := range r.Actions {
721			fmt.Printf("  action %d: %s\n", ar.Index, ar.Action)
722			fmt.Printf("    treasury:  %d -> %d\n", ar.Treasury.Before, ar.Treasury.After)
723			fmt.Printf("    %s: %d -> %d\n", ar.Recipient.Account, ar.Recipient.Before, ar.Recipient.After)
724		}
725	}
