		close(stop)
		rwg.Wait()

		if len(badReads) != 0 {
			t.Fatalf("round %d: readers observed %d corrupt/partial states:\n%s",
				round, len(badReads), strings.Join(badReads, "\n"))
		}
		if len(seenTreasureies) == 0 {
